        <h2>Hábitos</h2>''')
script='''
  <script>
    const BP_STORAGE_KEY = 'neodaemon.dashboard.bloodPressure.v1';

    function localDatetimeValue(date = new Date()) {
      const offsetMs = date.getTimezoneOffset() * 60000;
      return new Date(date.getTime() - offsetMs).toISOString().slice(0, 16);
    }

    function loadBpReadings() {
      try {
        return JSON.parse(localStorage.getItem(BP_STORAGE_KEY) || '[]')
          .filter(r => Number.isFinite(r.systolic) && Number.isFinite(r.diastolic) && r.recordedAt)
          .sort((a, b) => new Date(a.recordedAt) - new Date(b.recordedAt));
      } catch {
        return [];
      }
    }

    function saveBpReadings(readings) {
      localStorage.setItem(BP_STORAGE_KEY, JSON.stringify(readings));
    }

    function formatDate(value) {
      return new Intl.DateTimeFormat('es-ES', {
        dateStyle: 'short',
        timeStyle: 'short'
      }).format(new Date(value));
    }

    function drawBpChart(readings) {
      const canvas = document.getElementById('bp-chart');
      const ctx = canvas.getContext('2d');
      const w = canvas.width;
      const h = canvas.height;
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = '#0b1017';
      ctx.fillRect(0, 0, w, h);

      const pad = { left: 48, right: 18, top: 20, bottom: 34 };
      const minY = 40;
      const maxY = 200;
      const xFor = i => readings.length === 1
        ? (pad.left + (w - pad.left - pad.right) / 2)
        : pad.left + i * ((w - pad.left - pad.right) / (readings.length - 1));
      const yFor = value => pad.top + (maxY - value) * ((h - pad.top - pad.bottom) / (maxY - minY));

      ctx.strokeStyle = '#30363d';
      ctx.fillStyle = '#8b949e';
      ctx.font = '13px system-ui, sans-serif';
      [60, 80, 120, 140, 180].forEach(v => {
        const y = yFor(v);
        ctx.beginPath();
        ctx.moveTo(pad.left, y);
        ctx.lineTo(w - pad.right, y);
        ctx.stroke();
        ctx.fillText(String(v), 8, y + 4);
      });

      if (!readings.length) {
        ctx.fillStyle = '#8b949e';
        ctx.fillText('Añade tu primera lectura para ver la gráfica.', pad.left, h / 2);
        return;
      }

      function plot(key, color, label) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.beginPath();
        readings.forEach((r, i) => {
          const x = xFor(i);
          const y = yFor(r[key]);
          if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
        });
        ctx.stroke();
        readings.forEach((r, i) => {
          ctx.fillStyle = color;
          ctx.beginPath();
          ctx.arc(xFor(i), yFor(r[key]), 4, 0, Math.PI * 2);
          ctx.fill();
        });
        ctx.fillStyle = color;
        ctx.fillText(label, w - pad.right - 120, key === 'systolic' ? 22 : 42);
      }

      plot('systolic', '#ff7b72', 'Sistólica');
      plot('diastolic', '#58a6ff', 'Diastólica');

      ctx.fillStyle = '#8b949e';
      readings.forEach((r, i) => {
        if (i % Math.ceil(readings.length / 5) === 0 || i === readings.length - 1) {
          ctx.fillText(formatDate(r.recordedAt).replace(', ', '\n'), Math.max(48, xFor(i) - 28), h - 10);
        }
      });
    }

    function renderBp() {
      const readings = loadBpReadings();
      const body = document.getElementById('bp-table-body');
      if (!readings.length) {
        body.innerHTML = '<tr><td colspan="4" class="small">Todavía no hay lecturas.</td></tr>';
      } else {
        body.innerHTML = readings.slice().reverse().map(r => `
          <tr>
            <td>${formatDate(r.recordedAt)}</td>
            <td>${r.systolic}</td>
            <td>${r.diastolic}</td>
            <td>${r.pulse || '—'}</td>
          </tr>
        `).join('');
      }
      drawBpChart(readings);
    }

    document.addEventListener('DOMContentLoaded', () => {
      document.getElementById('bp-datetime').value = localDatetimeValue();
      document.getElementById('bp-form').addEventListener('submit', event => {
        event.preventDefault();
        const reading = {
          systolic: Number(document.getElementById('bp-sys').value),
          diastolic: Number(document.getElementById('bp-dia').value),
          pulse: document.getElementById('bp-pulse').value ? Number(document.getElementById('bp-pulse').value) : null,
          recordedAt: new Date(document.getElementById('bp-datetime').value).toISOString(),
          createdAt: new Date().toISOString()
        };
        const readings = loadBpReadings();
        readings.push(reading);
        saveBpReadings(readings);
        event.target.reset();
        document.getElementById('bp-datetime').value = localDatetimeValue();
        renderBp();
      });
      document.getElementById('bp-export').addEventListener('click', () => {
        const blob = new Blob([JSON.stringify(loadBpReadings(), null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'tension-arterial.json';
        a.click();
        URL.revokeObjectURL(url);
      });
      document.getElementById('bp-clear').addEventListener('click', () => {
        if (confirm('¿Borrar todos los registros de tensión arterial guardados en este navegador?')) {
          localStorage.removeItem(BP_STORAGE_KEY);
          renderBp();
        }
      });
      renderBp();
    });
  </script>
'''
s=s.replace('</body>
</html>
', script+'</body>
</html>
')
p.write_text(s)
