# Insert functions before document.addEventListener
insert = r'''
    function initDraggableCards() {
      const grid = document.querySelector('.grid');
      const cards = Array.from(grid.querySelectorAll('.card[data-card]'));
      const resetButton = document.getElementById('reset-layout');
      let dragged = null;

      function saveLayout() {
        const order = Array.from(grid.querySelectorAll('.card[data-card]')).map(card => card.dataset.card);
        localStorage.setItem(DASHBOARD_LAYOUT_KEY, JSON.stringify(order));
      }

      function applySavedLayout() {
        let order = [];
        try { order = JSON.parse(localStorage.getItem(DASHBOARD_LAYOUT_KEY) || '[]'); } catch { order = []; }
        if (!order.length) return;
        const cardsById = new Map(Array.from(grid.querySelectorAll('.card[data-card]')).map(card => [card.dataset.card, card]));
        const firstTechnicalKicker = Array.from(grid.querySelectorAll('.section-kicker')).find(k => k.textContent.includes('Observabilidad'));
        order.forEach(id => {
          const card = cardsById.get(id);
          if (card) grid.insertBefore(card, firstTechnicalKicker || null);
        });
      }

      function moveCard(target, event) {
        if (!dragged || dragged === target) return;
        const rect = target.getBoundingClientRect();
        const insertAfter = event.clientY > rect.top + rect.height / 2 || event.clientX > rect.left + rect.width / 2;
        grid.insertBefore(dragged, insertAfter ? target.nextSibling : target);
      }

      applySavedLayout();

      Array.from(grid.querySelectorAll('.card[data-card]')).forEach(card => {
