python3 - <<'PY'
from pathlib import Path
p=Path('/openclaw/workspace/dashboard/index.html')
s=p.read_text()
# CSS additions
s=s.replace('''    .subtitle { color: var(--muted); margin: 0; }''','''    .subtitle { color: var(--muted); margin: 0; }
    .header-actions { display: flex; gap: 8px; align-items: center; }
    .header-actions button { width: auto; margin: 0; padding: 7px 10px; font-size: .9rem; }
    .card { position: relative; }
    .card[draggable="true"] { cursor: grab; }
    .card[draggable="true"]:active { cursor: grabbing; }
    .card.dragging {
      opacity: .45;
      outline: 2px dashed var(--accent);
      outline-offset: 3px;
    }
    .card.drag-over {
      border-color: var(--accent);
      box-shadow: 0 0 0 1px rgba(88, 166, 255, .35);
    }
    .drag-hint { color: var(--muted); font-size: .8rem; margin-top: 6px; }''')
# Header add reset button
s=s.replace('''    <header>
      <h1>Dashboard MVP</h1>
      <p class="subtitle">Albert + neodaemon · local, privado, mínimo viable</p>
    </header>''','''    <header>
      <div>
        <h1>Dashboard MVP</h1>
        <p class="subtitle">Albert + neodaemon · local, privado, mínimo viable</p>
      </div>
      <div class="header-actions">
        <button class="secondary" id="reset-layout" type="button">Restaurar orden</button>
      </div>
    </header>''')
# Add card class and data-card ids in order
repls = {
'<section class="span-4 priority-card" id="blood-pressure-section">':'<section class="card span-4 priority-card" id="blood-pressure-section" data-card="blood-pressure">',
'<section class="span-2 technical priority-card">\n        <h2>Salud del sistema</h2>':'<section class="card span-2 technical priority-card" data-card="system-health">\n        <h2>Salud del sistema</h2>',
'<section class="compact priority-card">\n        <h2>Hoy</h2>':'<section class="card compact priority-card" data-card="today">\n        <h2>Hoy</h2>',
'<section class="compact">\n        <h2>Salud / movilidad</h2>':'<section class="card compact" data-card="health-mobility">\n        <h2>Salud / movilidad</h2>',
'<section class="compact">\n        <h2>Hábitos</h2>':'<section class="card compact" data-card="habits">\n        <h2>Hábitos</h2>',
'<section class="compact">\n        <h2>Pendientes / caos</h2>':'<section class="card compact" data-card="chaos">\n        <h2>Pendientes / caos</h2>',
'<section class="compact">\n        <h2>Seguridad</h2>':'<section class="card compact" data-card="security">\n        <h2>Seguridad</h2>',
'<section class="compact technical">\n        <h2>Uso LLM / tokens</h2>':'<section class="card compact technical" data-card="llm-tokens">\n        <h2>Uso LLM / tokens</h2>',
'<section class="span-2 technical">\n        <h2>Eficiencia · tokens por tarea útil</h2>':'<section class="card span-2 technical" data-card="token-efficiency">\n        <h2>Eficiencia · tokens por tarea útil</h2>',
'<section class="span-2 technical">\n        <h2>Tools / plugins</h2>':'<section class="card span-2 technical" data-card="tools-plugins">\n        <h2>Tools / plugins</h2>',
}
for old,new in repls.items():
    if old not in s:
        print('missing', old[:80])
    s=s.replace(old,new,1)
# Add hint before end grid if not present
s=s.replace('''        <span class="pill warn">Auditoría solo lectura · sin cambios</span>
      </section>
    </div>''','''        <span class="pill warn">Auditoría solo lectura · sin cambios</span>
      </section>
      <div class="section-kicker">Arrastra las tarjetas para reordenarlas. El orden se guarda en este navegador.</div>
    </div>''')
# Fix draggable script storage key and functions insert after BP_STORAGE_KEY
s=s.replace("    const BP_STORAGE_KEY = 'neodae…e.v1';", "    const BP_STORAGE_KEY = 'neodaemon.dashboard.bloodPressure.v1';\n    const DASHBOARD_LAYOUT_KEY = 'neodaemon.dashboard.layout.v1';")
# Insert functions before document.addEventListener
insert = r'''
    function initDraggableCards() {
      const grid = document.querySelector('.grid');
      const cards = Array.from(grid.querySelectorAll('.card[data-card]'));
      const resetButton = document.getElementById('reset-layout');
      let dragged = null;

      function saveLayout() {
        const order = Array.from(grid.querySelectorAll('.card[data-card]')).map(card => card.dataset.card);
        localStorage.setItem(DASHBOARD_LAYOUT_KEY, JSON.stringify(order));
      }

      function applySavedLayout() {
        let order = [];
        try { order = JSON.parse(localStorage.getItem(DASHBOARD_LAYOUT_KEY) || '[]'); } catch { order = []; }
        if (!order.length) return;
        const cardsById = new Map(Array.from(grid.querySelectorAll('.card[data-card]')).map(card => [card.dataset.card, card]));
        const firstTechnicalKicker = Array.from(grid.querySelectorAll('.section-kicker')).find(k => k.textContent.includes('Observabilidad'));
        order.forEach(id => {
          const card = cardsById.get(id);
          if (card) grid.insertBefore(card, firstTechnicalKicker || null);
        });
      }

      function moveCard(target, event) {
        if (!dragged || dragged === target) return;
        const rect = target.getBoundingClientRect();
        const insertAfter = event.clientY > rect.top + rect.height / 2 || event.clientX > rect.left + rect.width / 2;
        grid.insertBefore(dragged, insertAfter ? target.nextSibling : target);
      }

      applySavedLayout();

      Array.from(grid.querySelectorAll('.card[data-card]')).forEach(card => {
        card.draggable = true;
        card.title = 'Arrastra para mover esta tarjeta';
        card.addEventListener('dragstart', event => {
          dragged = card;
          card.classList.add('dragging');
          event.dataTransfer.effectAllowed = 'move';
          event.dataTransfer.setData('text/plain', card.dataset.card);
        });
        card.addEventListener('dragend', () => {
          card.classList.remove('dragging');
          Array.from(grid.querySelectorAll('.drag-over')).forEach(el => el.classList.remove('drag-over'));
          dragged = null;
          saveLayout();
        });
        card.addEventListener('dragover', event => {
          event.preventDefault();
          if (dragged && dragged !== card) card.classList.add('drag-over');
          moveCard(card, event);
        });
        card.addEventListener('dragleave', () => card.classList.remove('drag-over'));
        card.addEventListener('drop', event => {
          event.preventDefault();
          card.classList.remove('drag-over');
          moveCard(card, event);
          saveLayout();
        });
      });

      resetButton?.addEventListener('click', () => {
        localStorage.removeItem(DASHBOARD_LAYOUT_KEY);
        location.reload();
      });
    }
'''
s=s.replace('''    document.addEventListener('DOMContentLoaded', () => {''', insert+'''\n    document.addEventListener('DOMContentLoaded', () => {\n      initDraggableCards();''')
p.write_text(s)
PY
